using System; using System.Management; using System.Linq; class Program { static void Main() { try { var s = new ManagementObjectSearcher(@"Root\Microsoft\Windows\Storage", "SELECT * FROM MSFT_PhysicalDisk"); foreach(ManagementObject disk in s.Get()) { foreach(var p in disk.Properties) { if(p.Name.ToLower().Contains("wear")) Console.WriteLine(p.Name + "=" + p.Value); } } } catch (Exception e) { Console.WriteLine("ERR: " + e.Message); } } }
